sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    // Add your code here
    var messageBody = current.message_body.toString();

    var replace1 = messageBody.replaceAll("AA12", current.exchange);
    var replace2 = replace1.replaceAll("BB34", current.client);
    var replace3 = replace2.replaceAll("CC56", current.trade_date);
    var replace4 = replace3.replaceAll("DD78", current.value_date);

//MSSRBXCE-307-368 sn-14 requires to include client comments which from client email and stored in trade case form
if (current.servicenow_template_name == 'sn-14') {
    var tradeTask = new GlideRecord('x_hsb11_hsbc_mss_t_trade_task');
    tradeTask.addQuery('sys_id', current.servicenow_task_id);
    tradeTask.query();
    if (tradeTask.next())
        replace4 = replace4.replaceAll("EE0910", tradeTask.parent.client_comments);
}

	current.message_body = replace4;
	//current.update(); MSSRBXCE-601 commented for this defect.

})(current, previous);
